INSERT INTO public.cms_resources (slug, title, excerpt, cover_image, content, display_order, is_published) VALUES
(
  'proposal-and-publishing-forms',
  'Proposal and Publishing Forms',
  'Guidance and templates for submitting your book proposal and formalising the publishing agreement – used at the start of the process.',
  '/src/assets/resources/proposal-and-publishing-forms.jpg',
  E'To begin your publishing journey, you will need to submit a proposal and provide some initial documentation. This section brings together the key resources and forms that guide you through presenting your ideas for consideration and formalising the publication process.\n\n- **1.1 [Book Proposal Form](#)** - Outline and submit your book ideas for consideration\n- **1.2 [Guidelines for Adapting PhD Thesis](#)** - How to convert a PhD thesis into a publishable book\n- **1.3 [Guidelines for Adapting Conference Proceedings](#)** - How to convert conference proceedings into a publishable book\n- **1.4 [Contributor Agreement Form](#)** - Outlining terms for the publication of a work with Cambridge Scholars Publishing.',
  1,
  true
),
(
  'preparing-your-manuscript',
  'Preparing Your Manuscript',
  'Instructions on formatting, style, and submission requirements – needed when finalising your manuscript for production.',
  '/src/assets/resources/preparing-your-manuscript.jpg',
  E'When your proposal has been approved, the next step is to prepare your manuscript for submission. Here you will find guidance on formatting, referencing, permissions, and best practices to ensure your work meets professional publishing standards.\n\n- **2.1 [Submission Checklist](#)** - To ensure all necessary materials and requirements are completed before submitting a manuscript.\n- **2.2 [Manuscript Guidelines](#)** - Instructions and a sample layout for preparing manuscripts according to our publishing standards.\n- **2.3 [Referencing and Proofreading Guide](#)** - Guidance on proper citation, referencing, and best practices for thorough proofreading.\n- **2.4 [Marketing Your Book: Guidelines](#)** – Advice and strategies for promoting and marketing your book effectively.\n- **2.5 [Copyright and Permissions Pack](#)** - Information and forms for securing copyright and permissions for content used in your book.\n- **2.6 [BIC Codes](#)** - BIC codes to classify your book',
  2,
  true
),
(
  'preparing-your-book-cover',
  'Preparing Your Book Cover',
  'Guidelines for cover design elements, including images and author information – completed before the book enters production.',
  '/src/assets/resources/preparing-your-book-cover.jpg',
  E'A strong book cover is essential for both professional presentation and wider visibility. In this section, you will find the specifications and permissions guidance needed to design and submit your cover in line with publishing requirements.\n\n- **3.1 [Cover Guidelines and Specifications](#)** – Advice on selecting and preparing images suitable for your book cover.\n- **3.2 [External Permissions](#)** - Technical requirements and standards for designing and submitting a book cover.\n- **3.3 [Cover Image Permissions](#)** - Forms and instructions for obtaining legal permissions to use images in your book.\n- **3.4 [Cover Image Permissions - Parental Consent Form](#)** - Parental consent and copyright clearance for cover images featuring children.',
  3,
  true
),
(
  'post-publication',
  'Post Publication',
  'Resources on marketing, author discounts, and how to promote your book – used once your title is published.',
  '/src/assets/resources/post-publication.jpg',
  E'Publication marks the beginning of the next stage in your book''s journey. This section provides resources to help you promote your work, extend its reach, and ensure it has the greatest possible impact with your intended readership.\n\n- **4.1 [Promotion Information Form](#)** - Promotion Information Form',
  4,
  true
